10	// PreloadKnowledgeBases materializes every KB referenced by this classifier.
11	// Stable ordering makes startup diagnostics deterministic.
12	func (c *Classifier) PreloadKnowledgeBases() error {
13		if c == nil || len(c.kbClassifiers) == 0 {
14			return nil
15		}
16		names := make([]string, 0, len(c.kbClassifiers))
17		for name := range c.kbClassifiers {
18			names = append(names, name)
19		}
20		sort.Strings(names)
21		for _, name := range names {
22			if err := c.kbClassifiers[name].Preload(); err != nil {
23				return fmt.Errorf("preload knowledge base %q: %w", name, err)
24			}
25		}
26		return nil
27	}
