183	// newClassifierWithOptions creates a new classifier with the given options
184	func newClassifierWithOptions(cfg *config.RouterConfig, options ...option) (*Classifier, error) {
185		if cfg == nil {
186			return nil, fmt.Errorf("config is nil")
187		}
188	
189		classifier := &Classifier{Config: cfg}
190	
191		// Resolve identity header names from authz.identity config (or defaults).
192		classifier.authzUserIDHeader = cfg.Authz.Identity.GetUserIDHeader()
193		classifier.authzUserGroupsHeader = cfg.Authz.Identity.GetUserGroupsHeader()
194		classifier.authzFailOpen = cfg.Authz.FailOpen
195	
196		for _, option := range options {
197			option(classifier)
198		}
199	
200		// Build category name mappings to support generic categories in config
201		classifier.buildCategoryNameMappings()
202	
203		return classifier, nil
204	}
