3	import (
4		"strings"
5	
6		candle_binding "github.com/vllm-project/semantic-router/candle-binding"
7		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
8		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/utils/entropy"
9	)
10	
11	// matchDomainCategories returns the domain categories that exceed the configured
12	// threshold, using entropy analysis to decide between top-1 and multi-category output.
13	func (c *Classifier) matchDomainCategories(
14		domainResult candle_binding.ClassResultWithProbs,
15		topCategoryName string,
16	) []entropy.CategoryProbability {
17		threshold := c.Config.CategoryModel.Threshold
18		topMatch := domainResult.Confidence >= threshold && topCategoryName != ""
19	
20		if len(domainResult.Probabilities) == 0 {
21			if topMatch {
22				return []entropy.CategoryProbability{
23					{Category: topCategoryName, Probability: domainResult.Confidence},
24				}
25			}
26			return nil
27		}
28	
29		entropyResult := entropy.AnalyzeEntropy(domainResult.Probabilities)
30		logging.Debugf("[Signal Computation] Domain entropy analysis: entropy=%.3f, normalized=%.3f, uncertainty=%s",
31			entropyResult.Entropy, entropyResult.NormalizedEntropy, entropyResult.UncertaintyLevel)
32	
33		categoryNames := make([]string, len(domainResult.Probabilities))
34		for i := range domainResult.Probabilities {
35			if name, ok := c.CategoryMapping.GetCategoryFromIndex(i); ok {
36				categoryNames[i] = c.translateMMLUToGeneric(name)
37			}
38		}
39	
40		var matched []entropy.CategoryProbability
41		switch entropyResult.UncertaintyLevel {
42		case "very_low", "low":
43			if topMatch {
44				matched = []entropy.CategoryProbability{
45					{Category: topCategoryName, Probability: domainResult.Confidence},
46				}
47			}
48		default:
49			for i, prob := range domainResult.Probabilities {
50				if prob >= threshold && categoryNames[i] != "" {
51					matched = append(matched, entropy.CategoryProbability{
52						Category:    categoryNames[i],
53						Probability: prob,
54					})
55				}
56			}
57		}
58	
59		logging.Debugf("[Signal Computation] Domain signal matched %d categories (uncertainty=%s)",
60			len(matched), entropyResult.UncertaintyLevel)
61		return matched
62	}
63	
64	func (c *Classifier) buildCategoryNameMappings() {
65		c.MMLUToGeneric = make(map[string]string)
66		c.GenericToMMLU = make(map[string][]string)
67	
68		knownMMLU := make(map[string]bool)
69		if c.CategoryMapping != nil {
70			for _, label := range c.CategoryMapping.IdxToCategory {
71				knownMMLU[strings.ToLower(label)] = true
72			}
73		}
74	
75		for _, cat := range c.Config.Categories {
76			if len(cat.MMLUCategories) > 0 {
77				for _, mmlu := range cat.MMLUCategories {
78					key := strings.ToLower(mmlu)
79					c.MMLUToGeneric[key] = cat.Name
80					c.GenericToMMLU[cat.Name] = append(c.GenericToMMLU[cat.Name], mmlu)
81				}
82			} else {
83				nameLower := strings.ToLower(cat.Name)
84				if knownMMLU[nameLower] {
85					c.MMLUToGeneric[nameLower] = cat.Name
86					c.GenericToMMLU[cat.Name] = append(c.GenericToMMLU[cat.Name], cat.Name)
87				}
88			}
89		}
90	}
91	
92	// translateMMLUToGeneric translates an MMLU-Pro category to a generic category if mapping exists
93	func (c *Classifier) translateMMLUToGeneric(mmluCategory string) string {
94		if mmluCategory == "" {
95			return ""
96		}
97		if c.MMLUToGeneric == nil {
98			return mmluCategory
99		}
100		if generic, ok := c.MMLUToGeneric[strings.ToLower(mmluCategory)]; ok {
101			return generic
102		}
103		return mmluCategory
104	}
