1	package classification
2	
3	import (
4		"sync"
5		"time"
6	
7		candle_binding "github.com/vllm-project/semantic-router/candle-binding"
8		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
9		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
10	)
11	
12	// cachedJailbreakResult stores a cached jailbreak classification result.
13	type cachedJailbreakResult struct {
14		result candle_binding.ClassResult
15		err    error
16	}
17	
18	// collectJailbreakClassifierContents returns the deduplicated set of text pieces
19	// that need BERT classifier inference (contrastive rules are excluded).
20	func (c *Classifier) collectJailbreakClassifierContents(jailbreakText string, nonUserMessages []string) []string {
21		seen := make(map[string]struct{})
22		var contents []string
23		addUnique := func(s string) {
24			if s == "" {
25				return
26			}
27			if _, ok := seen[s]; !ok {
28				seen[s] = struct{}{}
29				contents = append(contents, s)
30			}
31		}
32		for _, rule := range c.Config.JailbreakRules {
33			if rule.Method == "contrastive" {
34				continue
35			}
36			addUnique(jailbreakText)
37			if !rule.IncludeHistory {
38				continue
39			}
40			for _, msg := range nonUserMessages {
41				addUnique(msg)
42			}
43		}
44		return contents
45	}
46	
47	func (c *Classifier) evaluateJailbreakSignal(results *SignalResults, mu *sync.Mutex, jailbreakText string, nonUserMessages []string) {
48		start := time.Now()
49	
50		// Step 1: Collect unique content pieces needed by classifier (non-contrastive) rules.
51		classifierContents := c.collectJailbreakClassifierContents(jailbreakText, nonUserMessages)
52	
53		// Step 2: Run classifier inference exactly once per unique content piece.
54		jailbreakCache := make(map[string][]cachedJailbreakResult, len(classifierContents))
55		for _, content := range classifierContents {
56			chunks := jailbreakSignalChunks(content)
57			cached := make([]cachedJailbreakResult, 0, len(chunks))
58			for _, chunk := range chunks {
59				result, err := c.jailbreakInference.Classify(chunk)
60				cached = append(cached, cachedJailbreakResult{result, err})
61			}
62			jailbreakCache[content] = cached
63		}
64	
65		// Step 3: Evaluate all rules concurrently.
66		var ruleWg sync.WaitGroup
67		for _, rule := range c.Config.JailbreakRules {
68			ruleWg.Add(1)
69			go func() {
70				defer ruleWg.Done()
71				c.evaluateJailbreakRule(rule, jailbreakText, nonUserMessages, jailbreakCache, start, results, mu)
72			}()
73		}
74		ruleWg.Wait()
75	
76		elapsed := time.Since(start)
77		latencySeconds := elapsed.Seconds()
78		results.Metrics.Jailbreak.ExecutionTimeMs = float64(elapsed.Microseconds()) / 1000.0
79		if results.JailbreakConfidence > 0 {
80			results.Metrics.Jailbreak.Confidence = float64(results.JailbreakConfidence)
81		}
82	
83		c.recordSignalExtraction(config.SignalTypeJailbreak, "jailbreak_evaluated", latencySeconds)
84		logging.Debugf("[Signal Computation] Jailbreak signal evaluation completed in %v", elapsed)
85	}
86	
87	func (c *Classifier) evaluateJailbreakRule(rule config.JailbreakRule, jailbreakText string, nonUserMessages []string, jailbreakCache map[string][]cachedJailbreakResult, start time.Time, results *SignalResults, mu *sync.Mutex) {
88		contentToAnalyze := buildContentList(jailbreakText, nonUserMessages, rule.IncludeHistory)
89		if len(contentToAnalyze) == 0 {
90			return
91		}
92	
93		switch rule.Method {
94		case "contrastive":
95			var chunks []string
96			for _, content := range contentToAnalyze {
97				chunks = append(chunks, jailbreakSignalChunks(content)...)
98			}
99			c.evaluateContrastiveJailbreakRule(rule, chunks, start, results, mu)
100		default:
101			c.evaluateBERTJailbreakRule(rule, contentToAnalyze, jailbreakCache, start, results, mu)
102		}
103	}
104	
105	// buildContentList assembles the text pieces to analyze for a single rule.
106	func buildContentList(text string, nonUserMessages []string, includeHistory bool) []string {
107		var content []string
108		if text != "" {
109			content = append(content, text)
110		}
111		if includeHistory && len(nonUserMessages) > 0 {
112			content = append(content, nonUserMessages...)
113		}
114		return content
115	}
116	
117	func (c *Classifier) evaluateContrastiveJailbreakRule(rule config.JailbreakRule, contentToAnalyze []string, start time.Time, results *SignalResults, mu *sync.Mutex) {
118		cjc, ok := c.contrastiveJailbreakClassifiers[rule.Name]
119		if !ok {
120			logging.Errorf("[Signal Computation] Contrastive jailbreak classifier not found for rule %q", rule.Name)
121			return
122		}
123		analysisResult := cjc.AnalyzeMessages(contentToAnalyze)
124		threshold := rule.Threshold
125		if threshold <= 0 {
126			threshold = 0.10
127		}
128		if analysisResult.MaxScore < threshold {
129			return
130		}
131	
132		c.recordSignalExtraction(config.SignalTypeJailbreak, rule.Name, time.Since(start).Seconds())
133		c.recordSignalMatch(config.SignalTypeJailbreak, rule.Name)
134	
135		confidence := analysisResult.MaxScore
136		mu.Lock()
137		results.MatchedJailbreakRules = append(results.MatchedJailbreakRules, rule.Name)
138		if confidence > results.JailbreakConfidence {
139			results.JailbreakDetected = true
140			results.JailbreakType = "contrastive"
141			results.JailbreakConfidence = confidence
142		}
143		results.SignalConfidences["jailbreak:"+rule.Name] = float64(confidence)
144		mu.Unlock()
145	
146		logging.Debugf("[Signal Computation] Contrastive jailbreak rule %q matched: score=%.4f threshold=%.4f worst_msg_idx=%d time=%v",
147			rule.Name, analysisResult.MaxScore, threshold, analysisResult.WorstMsgIndex, analysisResult.ProcessingTime)
148	}
149	
150	func (c *Classifier) evaluateBERTJailbreakRule(rule config.JailbreakRule, contentToAnalyze []string, jailbreakCache map[string][]cachedJailbreakResult, start time.Time, results *SignalResults, mu *sync.Mutex) {
151		bestType, bestConf := c.findBestJailbreakMatch(rule, contentToAnalyze, jailbreakCache)
152		if bestConf <= 0 {
153			return
154		}
155	
156		c.recordSignalExtraction(config.SignalTypeJailbreak, rule.Name, time.Since(start).Seconds())
157		c.recordSignalMatch(config.SignalTypeJailbreak, rule.Name)
158	
159		mu.Lock()
160		results.MatchedJailbreakRules = append(results.MatchedJailbreakRules, rule.Name)
161		if bestConf > results.JailbreakConfidence {
162			results.JailbreakDetected = true
163			results.JailbreakType = bestType
164			results.JailbreakConfidence = bestConf
165		}
166		results.SignalConfidences["jailbreak:"+rule.Name] = float64(bestConf)
167		mu.Unlock()
168	}
169	
170	// findBestJailbreakMatch scans cached BERT results and returns the highest-confidence jailbreak match.
171	func (c *Classifier) findBestJailbreakMatch(rule config.JailbreakRule, contentToAnalyze []string, jailbreakCache map[string][]cachedJailbreakResult) (string, float32) {
172		var bestType string
173		var bestConf float32
174		for _, content := range contentToAnalyze {
175			if content == "" {
176				continue
177			}
178			cachedResults, ok := jailbreakCache[content]
179			if !ok {
180				continue
181			}
182			for _, cached := range cachedResults {
183				if cached.err != nil {
184					logging.Errorf("[Signal Computation] Jailbreak rule %q: inference error: %v", rule.Name, cached.err)
185					continue
186				}
187				jailbreakType, ok := c.JailbreakMapping.GetJailbreakTypeFromIndex(cached.result.Class)
188				if !ok {
189					logging.Errorf("[Signal Computation] Jailbreak rule %q: unknown class index %d", rule.Name, cached.result.Class)
190					continue
191				}
192				if cached.result.Confidence < rule.Threshold || jailbreakType != "jailbreak" {
193					continue
194				}
195				if cached.result.Confidence > bestConf {
196					bestConf = cached.result.Confidence
197					bestType = jailbreakType
198				}
199			}
200		}
201		return bestType, bestConf
202	}
