13	// Provider computes text embeddings for router runtime features.
14	type Provider interface {
15		Embed(ctx context.Context, text string) ([]float32, error)
16		EmbedBatch(ctx context.Context, texts []string) ([][]float32, error)
17		Dimension() int
18		Backend() string
19	}
20	
21	type ProviderOptions struct {
22		BackendOverride string
23		HTTPClient      *http.Client
24	}
25	
26	type FuncProvider struct {
27		backend   string
28		dimension int
29		embed     func(context.Context, string) ([]float32, error)
30	}
31	
32	func BackendOverrideFromEnv() string {
33		return strings.ToLower(strings.TrimSpace(os.Getenv("EMBEDDING_BACKEND_OVERRIDE")))
34	}
35	
36	func NewProviderFromRouterConfig(cfg *config.RouterConfig, options ProviderOptions) (Provider, error) {
37		if cfg == nil {
38			return nil, fmt.Errorf("embedding provider config is nil")
39		}
40		return NewProvider(cfg.EmbeddingModels, options)
41	}
42	
43	func NewProvider(models config.EmbeddingModels, options ProviderOptions) (Provider, error) {
44		backend := resolveBackend(models, options.BackendOverride)
45		switch backend {
46		case config.EmbeddingBackendOpenAICompatible:
47			return NewOpenAICompatibleProvider(openAICompatibleConfigFromModels(models, options.HTTPClient))
48		default:
49			return nil, fmt.Errorf("unsupported embedding backend %q", backend)
50		}
51	}
