53	func NewFuncProvider(backend string, dimension int, embed func(context.Context, string) ([]float32, error)) (*FuncProvider, error) {
54		backend = strings.ToLower(strings.TrimSpace(backend))
55		if backend == "" {
56			return nil, fmt.Errorf("embedding backend is required")
57		}
58		if embed == nil {
59			return nil, fmt.Errorf("embedding function is required for backend %q", backend)
60		}
61		return &FuncProvider{backend: backend, dimension: dimension, embed: embed}, nil
62	}
63	
64	func (p *FuncProvider) Embed(ctx context.Context, text string) ([]float32, error) {
65		return p.embed(ctx, text)
66	}
67	
68	func (p *FuncProvider) EmbedBatch(ctx context.Context, texts []string) ([][]float32, error) {
69		embeddings := make([][]float32, len(texts))
70		for i, text := range texts {
71			embedding, err := p.Embed(ctx, text)
72			if err != nil {
73				return nil, err
74			}
75			embeddings[i] = embedding
76		}
77		return embeddings, nil
78	}
