88	func NewEmbeddingFunc(models config.EmbeddingModels, options ProviderOptions) (func(string) ([]float32, error), error) {
89		provider, err := NewProvider(models, options)
90		if err != nil {
91			return nil, err
92		}
93		return func(text string) ([]float32, error) {
94			return provider.Embed(context.Background(), text)
95		}, nil
96	}
97	
98	func resolveBackend(models config.EmbeddingModels, override string) string {
99		if normalized := strings.ToLower(strings.TrimSpace(override)); normalized != "" {
100			return normalized
101		}
102		return models.EmbeddingBackend()
103	}
