105	func openAICompatibleConfigFromModels(models config.EmbeddingModels, client *http.Client) OpenAICompatibleConfig {
106		expectedDimension := models.EmbeddingConfig.TargetDimension
107		if models.Endpoint.Dimensions > 0 {
108			expectedDimension = models.Endpoint.Dimensions
109		}
110		return OpenAICompatibleConfig{
