112			Model:             models.Endpoint.Model,
113			APIKeyEnv:         models.Endpoint.APIKeyEnv,
114			TimeoutSeconds:    models.Endpoint.TimeoutSeconds,
115			MaxRetries:        models.Endpoint.MaxRetries,
116			Dimensions:        models.Endpoint.Dimensions,
117			ExpectedDimension: expectedDimension,
118			HTTPClient:        client,
