3	// Package hnsw provides a Hierarchical Navigable Small World (HNSW) graph implementation
4	// for fast approximate nearest neighbor search on high-dimensional vectors.
5	//
6	// HNSW enables O(log n) similarity search compared to O(n) brute-force search,
7	// making it ideal for large-scale embedding similarity matching.
8	//
9	// Key features:
10	//   - O(log n) search complexity
11	//   - Configurable accuracy vs speed tradeoff via M and ef parameters
12	//   - SIMD-optimized distance calculations (AVX2/AVX-512)
13	//   - Thread-safe for concurrent reads
14	package hnsw
15	
16	import (
17		"cmp"
18		"math"
19		"math/rand/v2"
20		"slices"
21		"sync"
22	
23		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
24	)
25	
26	// Node represents a node in the HNSW graph
27	type Node struct {
28		ID        int           // Unique identifier for this node
29		Embedding []float32     // The embedding vector for this node
30		neighbors map[int][]int // Layer -> neighbor IDs
31		maxLayer  int           // Highest layer this node appears in
32	}
33	
34	// Index implements Hierarchical Navigable Small World graph for fast ANN search
35	type Index struct {
36		mu             sync.RWMutex
37		nodes          map[int]*Node // ID -> Node
38		entryPoint     int           // ID of the top-level entry point
39		maxLayer       int           // Maximum layer in the graph
40		efConstruction int           // Size of dynamic candidate list during construction
41		efSearch       int           // Size of dynamic candidate list during search
42		M              int           // Number of bi-directional links per node
43		Mmax           int           // Maximum number of connections per node (=M)
44		Mmax0          int           // Maximum number of connections for layer 0 (=M*2)
45		ml             float64       // Normalization factor for level assignment
46		nodeCount      int           // Total number of nodes
47	}
48	
49	// Config contains HNSW index configuration parameters
50	type Config struct {
51		// M is the number of bi-directional links per node (default: 16)
52		// Higher values improve recall but increase memory usage
53		M int
54	
55		// EfConstruction is the size of dynamic candidate list during construction (default: 200)
56		// Higher values improve index quality but increase build time
57		EfConstruction int
58	
59		// EfSearch is the size of dynamic candidate list during search (default: 50)
60		// Higher values improve search accuracy but increase latency
61		EfSearch int
62	}
63	
64	// DefaultConfig returns a Config with sensible default values
65	func DefaultConfig() Config {
66		return Config{
67			M:              16,
68			EfConstruction: 200,
69			EfSearch:       50,
70		}
71	}
72	
73	// SearchResult represents a single search result
74	type SearchResult struct {
75		ID         int     // Node ID
76		Similarity float32 // Cosine similarity score (higher is better)
77	}
78	
79	// NewIndex creates a new HNSW index with the given configuration
80	func NewIndex(cfg Config) *Index {
81		// Apply defaults for zero values
82		if cfg.M <= 0 {
83			cfg.M = 16
84		}
85		if cfg.EfConstruction <= 0 {
86			cfg.EfConstruction = 200
87		}
88		if cfg.EfSearch <= 0 {
89			cfg.EfSearch = 50
90		}
91	
92		return &Index{
93			nodes:          make(map[int]*Node),
94			entryPoint:     -1,
95			maxLayer:       -1,
96			efConstruction: cfg.EfConstruction,
97			efSearch:       cfg.EfSearch,
98			M:              cfg.M,
99			Mmax:           cfg.M,
100			Mmax0:          cfg.M * 2,
101			ml:             1.0 / math.Log(float64(cfg.M)),
102		}
103	}
104	
105	// Add inserts a new node with the given ID and embedding into the index
106	func (h *Index) Add(id int, embedding []float32) {
107		h.mu.Lock()
108		defer h.mu.Unlock()
109	
110		h.addNode(id, embedding)
111	}
112	
113	// AddBatch inserts multiple nodes into the index
114	func (h *Index) AddBatch(embeddings map[int][]float32) {
115		h.mu.Lock()
116		defer h.mu.Unlock()
117	
118		for id, embedding := range embeddings {
119			h.addNode(id, embedding)
120		}
121	}
122	
123	// Search finds the k most similar nodes to the query embedding
124	// Returns results sorted by similarity (highest first)
125	func (h *Index) Search(queryEmbedding []float32, k int) []SearchResult {
126		return h.SearchWithEf(queryEmbedding, k, 0)
127	}
128	
129	// SearchWithEf finds the k most similar nodes with explicit ef parameter
130	// If ef <= 0, uses max(efSearch, k) as default
131	// Returns results sorted by similarity (highest first)
132	func (h *Index) SearchWithEf(queryEmbedding []float32, k int, ef int) []SearchResult {
133		h.mu.RLock()
134		defer h.mu.RUnlock()
135	
136		if h.entryPoint == -1 || len(h.nodes) == 0 {
137			return []SearchResult{}
138		}
139	
140		// Search from top layer to layer 1
141		currentNearest := h.entryPoint
142		for lc := h.maxLayer; lc > 0; lc-- {
143			nearest := h.searchLayer(queryEmbedding, currentNearest, 1, lc)
144			if len(nearest) > 0 {
145				currentNearest = nearest[0]
146			}
147		}
148	
149		// Determine ef for layer 0 search
150		if ef <= 0 {
151			ef = h.efSearch
152			if ef < k {
153				ef = k
154			}
155		}
156	
157		// For very large ef values, cap at 2x the total node count to avoid excessive computation
158		maxEf := len(h.nodes) * 2
159		if ef > maxEf {
160			ef = maxEf
161		}
162	
163		candidateIDs := h.searchLayer(queryEmbedding, currentNearest, ef, 0)
164	
165		// Convert to SearchResults with similarities
166		results := make([]SearchResult, 0, len(candidateIDs))
167		for _, id := range candidateIDs {
168			if node, ok := h.nodes[id]; ok {
169				similarity := dotProductSIMD(queryEmbedding, node.Embedding)
170				results = append(results, SearchResult{
171					ID:         id,
172					Similarity: similarity,
173				})
174				logging.Infof("[HNSW path] candidate[%d], similarity=%.4f", id, similarity)
175			}
176		}
177	
178		// Sort by similarity (descending) and return top k
179		sortBySimDesc(results)
180		if len(results) > k {
181			results = results[:k]
182		}
183	
184		return results
185	}
186	
187	// SearchAll performs a brute-force search against all nodes
188	// Useful for small indices or when exact results are needed
189	func (h *Index) SearchAll(queryEmbedding []float32, k int) []SearchResult {
190		h.mu.RLock()
191		defer h.mu.RUnlock()
192	
193		results := make([]SearchResult, 0, len(h.nodes))
194		for id, node := range h.nodes {
195			similarity := dotProductSIMD(queryEmbedding, node.Embedding)
196			results = append(results, SearchResult{
197				ID:         id,
198				Similarity: similarity,
199			})
200		}
201	
202		sortBySimDesc(results)
203		if len(results) > k {
204			results = results[:k]
205		}
206	
207		return results
208	}
209	
210	// Size returns the number of nodes in the index
211	func (h *Index) Size() int {
212		h.mu.RLock()
213		defer h.mu.RUnlock()
214		return len(h.nodes)
215	}
216	
217	// GetEmbedding returns the embedding for a given node ID
218	func (h *Index) GetEmbedding(id int) ([]float32, bool) {
219		h.mu.RLock()
220		defer h.mu.RUnlock()
221	
222		if node, ok := h.nodes[id]; ok {
223			return node.Embedding, true
224		}
225		return nil, false
226	}
227	
228	// Clear removes all nodes from the index
229	func (h *Index) Clear() {
230		h.mu.Lock()
231		defer h.mu.Unlock()
232	
233		h.nodes = make(map[int]*Node)
234		h.entryPoint = -1
235		h.maxLayer = -1
236		h.nodeCount = 0
237	}
238	
239	// ===== Internal Implementation =====
240	
241	// selectLevel randomly selects a level for a new node
242	func (h *Index) selectLevel() int {
243		r := -math.Log(math.Max(1e-9, 1.0-rand.Float64()))
244		return int(r * h.ml)
245	}
246	
247	// addNode adds a new node to the HNSW index (caller must hold write lock)
248	func (h *Index) addNode(id int, embedding []float32) {
249		level := h.selectLevel()
250	
251		node := &Node{
252			ID:        id,
253			Embedding: embedding,
254			neighbors: make(map[int][]int),
255			maxLayer:  level,
256		}
257	
258		// If this is the first node, make it the entry point
259		if h.entryPoint == -1 {
260			h.entryPoint = id
261			h.maxLayer = level
262			h.nodes[id] = node
263			h.nodeCount++
264			return
265		}
266	
267		// Find nearest neighbors and connect
268		for lc := min(level, h.maxLayer); lc >= 0; lc-- {
269			candidates := h.searchLayer(embedding, h.entryPoint, h.efConstruction, lc)
270	
271			// Select M nearest neighbors
272			M := h.Mmax
273			if lc == 0 {
274				M = h.Mmax0
275			}
276			neighbors := h.selectNeighbors(candidates, M, embedding)
277	
278			// Add bidirectional links
279			node.neighbors[lc] = neighbors
280			for _, neighborID := range neighbors {
281				if n, ok := h.nodes[neighborID]; ok {
282					if n.neighbors[lc] == nil {
283						n.neighbors[lc] = []int{}
284					}
285					n.neighbors[lc] = append(n.neighbors[lc], id)
286	
287					// Prune neighbors if needed
288					if len(n.neighbors[lc]) > M {
289						n.neighbors[lc] = h.selectNeighbors(n.neighbors[lc], M, n.Embedding)
290					}
291				}
292			}
293		}
294	
295		// Update entry point if this node has a higher level
296		if level > h.maxLayer {
297			h.maxLayer = level
298			h.entryPoint = id
299		}
300	
301		h.nodes[id] = node
302		h.nodeCount++
303	}
304	
305	// searchLayer searches for nearest neighbors at a specific layer
306	func (h *Index) searchLayer(queryEmbedding []float32, entryPoint, ef, layer int) []int {
307		visited := make(map[int]bool)
308		candidates := newMinHeap()
309		results := newMaxHeap()
310	
311		// Calculate distance to entry point
312		if entryNode, ok := h.nodes[entryPoint]; ok {
313			dist := h.distance(queryEmbedding, entryNode.Embedding)
314			candidates.push(entryPoint, dist)
315			results.push(entryPoint, dist)
316			visited[entryPoint] = true
317		}
318	
319		for candidates.len() > 0 {
320			currentID, currentDist := candidates.pop()
321	
322			// If we have enough results and current is worse than worst result, stop
323			if results.len() > 0 && currentDist > results.peekDist() {
324				break
325			}
326	
327			currentNode, ok := h.nodes[currentID]
328			if !ok || currentNode.neighbors[layer] == nil {
329				continue
330			}
331	
332			// Check neighbors
333			for _, neighborID := range currentNode.neighbors[layer] {
334				if visited[neighborID] {
335					continue
336				}
337				visited[neighborID] = true
338				h.tryAddNeighbor(queryEmbedding, neighborID, ef, candidates, results)
339			}
340		}
341	
342		return results.items()
343	}
344	
345	// tryAddNeighbor evaluates a single neighbor and pushes it into the search
346	// heaps when it improves the current top-ef result set.
347	func (h *Index) tryAddNeighbor(queryEmbedding []float32, neighborID, ef int, candidates *minHeap, results *maxHeap) {
348		neighborNode, ok := h.nodes[neighborID]
349		if !ok {
350			return
351		}
352		dist := h.distance(queryEmbedding, neighborNode.Embedding)
353	
354		if results.len() >= ef && dist >= results.peekDist() {
355			return
356		}
357	
358		candidates.push(neighborID, dist)
359		results.push(neighborID, dist)
360		if results.len() > ef {
361			results.pop()
362		}
363	}
364	
365	// selectNeighbors selects the best neighbors by sorting by distance
366	func (h *Index) selectNeighbors(candidateIDs []int, m int, queryEmb []float32) []int {
367		if len(queryEmb) == 0 {
368			return []int{}
369		}
370	
371		if len(candidateIDs) <= m {
372			return candidateIDs
373		}
374	
375		type neighborDist struct {
376			id   int
377			dist float32
378		}
379	
380		neighbors := make([]neighborDist, 0, len(candidateIDs))
381		for _, id := range candidateIDs {
382			node, ok := h.nodes[id]
383			if !ok || len(node.Embedding) != len(queryEmb) {
384				continue
385			}
386			neighbors = append(neighbors, neighborDist{
387				id:   id,
388				dist: h.distance(queryEmb, node.Embedding),
389			})
390		}
391	
392		slices.SortFunc(neighbors, func(a, b neighborDist) int {
393			return cmp.Compare(a.dist, b.dist)
394		})
395	
396		if m > len(neighbors) {
397			m = len(neighbors)
398		}
399		result := make([]int, 0, m)
400		for i := 0; i < m; i++ {
401			result = append(result, neighbors[i].id)
402		}
403		return result
404	}
405	
406	// distance calculates cosine distance (lower is more similar)
407	// Uses negative dot product since embeddings are normalized
408	func (h *Index) distance(a, b []float32) float32 {
409		dotProduct := dotProductSIMD(a, b)
410		return -dotProduct // Negate so higher similarity = lower distance
411	}
412	
413	// sortBySimDesc sorts SearchResults by similarity in descending order
414	func sortBySimDesc(results []SearchResult) {
415		// Simple insertion sort - efficient for small slices
416		for i := 1; i < len(results); i++ {
417			for j := i; j > 0 && results[j].Similarity > results[j-1].Similarity; j-- {
418				results[j], results[j-1] = results[j-1], results[j]
419			}
420		}
421	}
