423	// ===== Priority Queue Implementations =====
424	
425	type heapItem struct {
426		id   int
427		dist float32
428	}
429	
430	type minHeap struct {
431		data []heapItem
432	}
433	
434	func newMinHeap() *minHeap {
435		return &minHeap{data: []heapItem{}}
436	}
437	
438	func (h *minHeap) push(id int, dist float32) {
439		h.data = append(h.data, heapItem{id, dist})
440		h.bubbleUp(len(h.data) - 1)
441	}
442	
443	func (h *minHeap) pop() (int, float32) {
444		if len(h.data) == 0 {
445			return -1, 0
446		}
447		result := h.data[0]
448		h.data[0] = h.data[len(h.data)-1]
449		h.data = h.data[:len(h.data)-1]
450		if len(h.data) > 0 {
451			h.bubbleDown(0)
452		}
453		return result.id, result.dist
454	}
455	
456	func (h *minHeap) len() int {
457		return len(h.data)
458	}
459	
460	func (h *minHeap) bubbleUp(i int) {
461		for i > 0 {
462			parent := (i - 1) / 2
463			if h.data[i].dist >= h.data[parent].dist {
464				break
465			}
466			h.data[i], h.data[parent] = h.data[parent], h.data[i]
467			i = parent
468		}
469	}
470	
471	func (h *minHeap) bubbleDown(i int) {
472		for {
473			left := 2*i + 1
474			right := 2*i + 2
475			smallest := i
476	
477			if left < len(h.data) && h.data[left].dist < h.data[smallest].dist {
478				smallest = left
479			}
480			if right < len(h.data) && h.data[right].dist < h.data[smallest].dist {
481				smallest = right
482			}
483			if smallest == i {
484				break
485			}
486			h.data[i], h.data[smallest] = h.data[smallest], h.data[i]
487			i = smallest
488		}
489	}
490	
491	type maxHeap struct {
492		data []heapItem
493	}
494	
495	func newMaxHeap() *maxHeap {
496		return &maxHeap{data: []heapItem{}}
497	}
498	
499	func (h *maxHeap) push(id int, dist float32) {
500		h.data = append(h.data, heapItem{id, dist})
501		h.bubbleUp(len(h.data) - 1)
502	}
503	
504	func (h *maxHeap) pop() (int, float32) {
505		if len(h.data) == 0 {
506			return -1, 0
507		}
508		result := h.data[0]
509		h.data[0] = h.data[len(h.data)-1]
510		h.data = h.data[:len(h.data)-1]
511		if len(h.data) > 0 {
512			h.bubbleDown(0)
513		}
514		return result.id, result.dist
515	}
516	
517	func (h *maxHeap) len() int {
518		return len(h.data)
519	}
520	
521	func (h *maxHeap) peekDist() float32 {
522		if len(h.data) == 0 {
523			return math.MaxFloat32
524		}
525		return h.data[0].dist
526	}
527	
528	func (h *maxHeap) items() []int {
529		result := make([]int, len(h.data))
530		for i, item := range h.data {
531			result[i] = item.id
532		}
533		return result
534	}
535	
536	func (h *maxHeap) bubbleUp(i int) {
537		for i > 0 {
538			parent := (i - 1) / 2
539			if h.data[i].dist <= h.data[parent].dist {
540				break
541			}
542			h.data[i], h.data[parent] = h.data[parent], h.data[i]
543			i = parent
544		}
545	}
546	
547	func (h *maxHeap) bubbleDown(i int) {
548		for {
549			left := 2*i + 1
550			right := 2*i + 2
551			largest := i
552	
553			if left < len(h.data) && h.data[left].dist > h.data[largest].dist {
554				largest = left
555			}
556			if right < len(h.data) && h.data[right].dist > h.data[largest].dist {
557				largest = right
558			}
559			if largest == i {
560				break
561			}
562			h.data[i], h.data[largest] = h.data[largest], h.data[i]
563			i = largest
564		}
565	}
