1	// Package milvus provides shared connection, collection ensure/load, and retry
2	// helpers for Milvus-backed runtime stores (memory, cache, vectorstore,
3	// routerreplay, etc.). Domain packages keep schema and query semantics; use
4	// this package for duplicated lifecycle mechanics (see GitHub issue #1601).
5	package milvus
6	
7	import (
8		"context"
9		"fmt"
10		"strings"
11		"time"
12	
13		"github.com/milvus-io/milvus-sdk-go/v2/client"
14	)
15	
16	// LifecycleClient captures the subset of Milvus client lifecycle APIs reused by
17	// runtime stores.
18	type LifecycleClient interface {
19		HasCollection(ctx context.Context, collectionName string) (bool, error)
20		LoadCollection(ctx context.Context, collectionName string, async bool, opts ...client.LoadCollectionOption) error
21	}
22	
23	// CollectionRetryOptions controls retry behavior for collection lifecycle
24	// operations during backend startup.
25	type CollectionRetryOptions struct {
26		Attempts  int
27		BaseDelay time.Duration
28	}
29	
30	func normalizedCollectionRetryOptions(opts CollectionRetryOptions) CollectionRetryOptions {
31		if opts.Attempts <= 0 {
32			opts.Attempts = 3
33		}
34		if opts.BaseDelay <= 0 {
35			opts.BaseDelay = 2 * time.Second
36		}
37		return opts
38	}
39	
40	// ConnectGRPC creates a Milvus gRPC client with an optional timeout.
41	func ConnectGRPC(ctx context.Context, address string, timeout time.Duration) (client.Client, error) {
42		if address == "" {
43			return nil, fmt.Errorf("milvus address is required")
44		}
45	
46		dialCtx := ctx
47		cancel := func() {}
48		if timeout > 0 {
49			dialCtx, cancel = context.WithTimeout(ctx, timeout)
50		}
51		defer cancel()
52	
53		milvusClient, err := client.NewGrpcClient(dialCtx, address)
54		if err != nil {
55			return nil, fmt.Errorf("failed to connect to Milvus at %s: %w", address, err)
56		}
57	
58		return milvusClient, nil
59	}
