61	// Connect creates a Milvus SDK client (with username/password support) with an optional timeout.
62	func Connect(ctx context.Context, cfg client.Config, timeout time.Duration) (client.Client, error) {
63		if cfg.Address == "" {
64			return nil, fmt.Errorf("milvus address is required")
65		}
66	
67		dialCtx := ctx
68		cancel := func() {}
69		if timeout > 0 {
70			dialCtx, cancel = context.WithTimeout(ctx, timeout)
71		}
72		defer cancel()
73	
74		milvusClient, err := client.NewClient(dialCtx, cfg)
75		if err != nil {
76			return nil, fmt.Errorf("failed to connect to Milvus at %s: %w", cfg.Address, err)
77		}
78		return milvusClient, nil
79	}
