81	// EnsureCollectionLoaded ensures collection lifecycle is handled consistently:
82	// create when missing and load for queries.
83	func EnsureCollectionLoaded(
84		ctx context.Context,
85		milvusClient LifecycleClient,
86		collectionName string,
87		createIfMissing func(context.Context) error,
88	) error {
89		return EnsureCollectionLoadedWithHooks(ctx, milvusClient, collectionName, createIfMissing, nil)
90	}
91	
92	// EnsureCollectionLoadedWithHooks extends EnsureCollectionLoaded with an optional
93	// hook when the collection already exists.
94	func EnsureCollectionLoadedWithHooks(
95		ctx context.Context,
96		milvusClient LifecycleClient,
97		collectionName string,
98		createIfMissing func(context.Context) error,
99		onExists func(context.Context) error,
100	) error {
101		if createIfMissing == nil {
102			return fmt.Errorf("createIfMissing callback must not be nil")
103		}
104	
105		exists, err := milvusClient.HasCollection(ctx, collectionName)
106		if err != nil {
107			return fmt.Errorf("failed to check collection %s: %w", collectionName, err)
108		}
109	
110		if exists && onExists != nil {
111			if err := onExists(ctx); err != nil {
112				return fmt.Errorf("failed to validate existing collection %s: %w", collectionName, err)
113			}
114		}
115		if !exists {
116			if err := createIfMissing(ctx); err != nil {
117				return fmt.Errorf("failed to create collection %s: %w", collectionName, err)
118			}
119		}
120	
121		if err := milvusClient.LoadCollection(ctx, collectionName, false); err != nil {
122			return fmt.Errorf("failed to load collection %s: %w", collectionName, err)
123		}
124		return nil
125	}
126	
127	// EnsureCollectionLoadedWithRetry retries collection lifecycle operations when
128	// Milvus is running but still converging internal node or metadata state.
129	func EnsureCollectionLoadedWithRetry(
130		ctx context.Context,
131		milvusClient LifecycleClient,
132		collectionName string,
133		createIfMissing func(context.Context) error,
134		opts CollectionRetryOptions,
135	) error {
136		return EnsureCollectionLoadedWithHooksRetry(ctx, milvusClient, collectionName, createIfMissing, nil, opts)
137	}
138	
139	// EnsureCollectionLoadedWithHooksRetry extends EnsureCollectionLoadedWithHooks
140	// with bounded retries for transient Milvus startup/lifecycle failures.
141	func EnsureCollectionLoadedWithHooksRetry(
142		ctx context.Context,
143		milvusClient LifecycleClient,
144		collectionName string,
145		createIfMissing func(context.Context) error,
146		onExists func(context.Context) error,
147		opts CollectionRetryOptions,
148	) error {
149		retryOpts := normalizedCollectionRetryOptions(opts)
150		return RetryIf(
151			ctx,
152			retryOpts.Attempts,
153			retryOpts.BaseDelay,
154			fmt.Sprintf("ensure/load collection %s", collectionName),
155			func(innerCtx context.Context) error {
156				return EnsureCollectionLoadedWithHooks(innerCtx, milvusClient, collectionName, createIfMissing, onExists)
157			},
158			IsTransientLifecycleError,
159		)
160	}
161	
162	// IsTransientLifecycleError identifies Milvus lifecycle errors that can appear
163	// while standalone Milvus has opened its gRPC port but is still reconciling
164	// proxy/data node metadata after a restart.
165	func IsTransientLifecycleError(err error) bool {
166		if err == nil {
167			return false
168		}
169		msg := strings.ToLower(err.Error())
170		transientMarkers := []string{
171			"context deadline exceeded",
172			"connection refused",
173			"grpc: the client connection is closing",
174			"invalidatecollectionmetacache failed",
175			"node not match",
176			"server is not ready",
177			"transport is closing",
178			"unavailable",
179		}
180		for _, marker := range transientMarkers {
181			if strings.Contains(msg, marker) {
182				return true
183			}
184		}
185		return false
186	}
187	
188	// Retry retries lifecycle operations with bounded exponential backoff.
189	func Retry(
190		ctx context.Context,
191		attempts int,
192		baseDelay time.Duration,
193		opName string,
194		op func(context.Context) error,
195	) error {
196		return RetryIf(ctx, attempts, baseDelay, opName, op, func(error) bool { return true })
197	}
198	
199	// RetryIf retries lifecycle operations with bounded exponential backoff while
200	// the supplied predicate marks failures as retryable.
201	func RetryIf(
202		ctx context.Context,
203		attempts int,
204		baseDelay time.Duration,
205		opName string,
206		op func(context.Context) error,
207		shouldRetry func(error) bool,
208	) error {
209		if opName == "" {
210			opName = "operation"
211		}
212		if op == nil {
213			return fmt.Errorf("%s function is nil", opName)
214		}
215	
216		if attempts <= 0 {
217			attempts = 1
218		}
219		if baseDelay <= 0 {
220			baseDelay = 200 * time.Millisecond
221		}
222	
223		var lastErr error
224		for i := 0; i < attempts; i++ {
225			if err := op(ctx); err == nil {
226				return nil
227			} else {
228				lastErr = err
229				if shouldRetry != nil && !shouldRetry(err) {
230					return fmt.Errorf("%s failed with non-retryable error: %w", opName, err)
231				}
232			}
233	
234			if i == attempts-1 {
235				break
236			}
237	
238			delay := baseDelay * time.Duration(1<<i)
239			select {
240			case <-ctx.Done():
241				return fmt.Errorf("%s aborted: %w", opName, ctx.Err())
242			case <-time.After(delay):
243			}
244		}
245	
246		return fmt.Errorf("%s failed after %d attempt(s): %w", opName, attempts, lastErr)
247	}
