27	func CompileAST(prog *Program) (*config.RouterConfig, []error) {
28		defaults := config.DefaultGlobalConfig()
29		c := &Compiler{
30			prog: prog,
31			config: &config.RouterConfig{
32				IntelligentRouting: config.IntelligentRouting{
33					ModelSelection: defaults.ModelSelection,
34				},
35			},
36			pluginTemplates: make(map[string]*PluginDecl),
37		}
38		c.config.Strategy = config.RoutingStrategy(prog.Strategy)
39		c.compile()
40		c.compileScopes()
41		if len(c.errors) > 0 {
42			return nil, c.errors
43		}
