138	func (c *Compiler) validateEmitForCompile(r *RouteDecl, e *EmitDecl) bool {
139		if e == nil {
140			return false
141		}
142		context := fmt.Sprintf("ROUTE %s EMIT", r.Name)
143		if !supportedEmitKinds[e.Kind] {
144			c.addError(e.Pos, "%s: unknown EMIT kind %q. Supported kinds: retention", context, e.Kind)
145			return false
146		}
147		if e.Kind != emitKindRetention {
148			return true
149		}
150		ok := true
151		for _, issue := range retentionRawFieldDiagnostics(e, context) {
152			c.addError(issue.pos, "%s", issue.message)
153			ok = false
154		}
155		if e.Retention == nil {
156			return ok
157		}
158		if e.Retention.TTLTurns != nil && *e.Retention.TTLTurns < 0 {
159			c.addError(e.Pos, "%s retention: ttl_turns must be >= 0, got %d", context, *e.Retention.TTLTurns)
160			ok = false
161		}
162		if e.Retention.Drop != nil && *e.Retention.Drop && e.Retention.TTLTurns != nil && *e.Retention.TTLTurns > 0 {
163			c.addError(e.Pos, "%s retention: drop=true conflicts with ttl_turns=%d. Use one or the other", context, *e.Retention.TTLTurns)
164			ok = false
165		}
166		return ok
167	}
