9		"github.com/alecthomas/participle/v2/lexer"
10	)
11	
12	// dslLexer defines the lexical rules for the DSL.
13	var dslLexer = lexer.MustSimple([]lexer.SimpleRule{
14		{Name: "Comment", Pattern: `#[^\n]*`},
15		{Name: "Whitespace", Pattern: `[\s]+`},
16		{Name: "Float", Pattern: `[+-]?[0-9]+\.[0-9]+`},
17		{Name: "Int", Pattern: `[+-]?[0-9]+`},
18		{Name: "String", Pattern: `"(?:[^"\\]|\\.)*"`},
19		{Name: "Arrow", Pattern: `->|→`},
20		{Name: "Ident", Pattern: `[a-zA-Z_][a-zA-Z0-9_\-\.\/]*`},
21		{Name: "LBrace", Pattern: `\{`},
22		{Name: "RBrace", Pattern: `\}`},
23		{Name: "LParen", Pattern: `\(`},
24		{Name: "RParen", Pattern: `\)`},
25		{Name: "LBracket", Pattern: `\[`},
26		{Name: "RBracket", Pattern: `\]`},
27		{Name: "Colon", Pattern: `:`},
28		{Name: "Comma", Pattern: `,`},
29		{Name: "GreaterThan", Pattern: `>`},
30		{Name: "Equals", Pattern: `=`},
31	})
32	
33	// rawParser is the participle parser for the DSL.
34	var rawParser = participle.MustBuild[rawProgram](
35		participle.Lexer(dslLexer),
36		participle.Elide("Comment", "Whitespace"),
37		participle.UseLookahead(3),
38	)
39	
40	// Parse tokenizes and parses a DSL source string into a Program AST.
41	// If the input has syntax errors, Parse attempts error recovery by
42	// splitting the input into top-level blocks and parsing each independently.
43	func Parse(input string) (*Program, []error) {
44		raw, err := rawParser.ParseString("", input)
45		if err == nil {
46			return rawToProgram(raw)
47		}
48	
49		// Error recovery: split input into top-level blocks and parse each
50		blocks := splitTopLevelBlocks(input)
51		if len(blocks) <= 1 {
52			return nil, []error{err}
53		}
54	
55		prog := &Program{}
56		var allErrors []error
57		parsedAny := false
58		for _, block := range blocks {
59			block = strings.TrimSpace(block)
60			if block == "" {
61				continue
62			}
63			r, e := rawParser.ParseString("", block)
64			if e != nil {
65				allErrors = append(allErrors, e)
66				continue
67			}
68			parsedAny = true
69			resolved, lowerErrs := rawToProgram(r)
70			mergeProgram(prog, resolved)
71			allErrors = append(allErrors, lowerErrs...)
72		}
73	
74		if !parsedAny {
75			return nil, []error{err}
76		}
77		return prog, allErrors
78	}
