80	// splitTopLevelBlocks splits DSL source into top-level blocks by finding
81	// top-level keywords (SIGNAL, ROUTE, MODEL, PLUGIN) that appear outside of
82	// braces.
83	func splitTopLevelBlocks(input string) []string {
84		var blocks []string
85		depth := 0
86		start := 0
87		keywords := []string{
88			"DECISION_TREE", "ENTRYPOINT", "PROJECTION", "ROUTING", "RECIPE",
89			"SIGNAL", "ROUTE", "MODEL", "PLUGIN", "TEST",
90		}
91	
92		for i := 0; i < len(input); i++ {
93			ch := input[i]
94			if ch == '"' {
95				// skip string literals
96				i++
97				for i < len(input) && input[i] != '"' {
98					if input[i] == '\\' {
99						i++
100					}
101					i++
102				}
103				continue
104			}
105			if ch == '#' {
106				// skip comments
107				for i < len(input) && input[i] != '\n' {
108					i++
109				}
110				continue
111			}
112			if ch == '{' {
113				depth++
114				continue
115			}
116			if ch == '}' {
117				depth--
118				continue
119			}
120			if depth == 0 {
121				for _, kw := range keywords {
122					if i+len(kw) <= len(input) && input[i:i+len(kw)] == kw {
123						// Check that it's at a word boundary
124						if i > 0 && isIdentPart(rune(input[i-1])) {
125							continue
126						}
127						if i+len(kw) < len(input) && isIdentPart(rune(input[i+len(kw)])) {
128							continue
129						}
130						// Found a top-level keyword — split here
131						if i > start {
132							blocks = append(blocks, input[start:i])
133						}
134						start = i
135						break
136					}
137				}
138			}
139		}
140		if start < len(input) {
141			blocks = append(blocks, input[start:])
142		}
143		return blocks
144	}
