148	func rawToProgram(raw *rawProgram) (*Program, []error) {
149		prog := &Program{}
150		var errs []error
151		hasDirectRoutes := false
152		treeCount := 0
153		for _, entry := range raw.Entries {
154			switch {
155			case entry.Routing != nil:
156				errs = append(errs, applyRawRouting(prog, entry.Routing)...)
157			case entry.Entrypoint != nil:
158				decl, entryErrs := rawToEntrypoint(entry.Entrypoint)
159				prog.Entrypoints = append(prog.Entrypoints, decl)
160				errs = append(errs, entryErrs...)
161			case entry.Recipe != nil:
162				decl, recipeErrs := rawToRecipe(entry.Recipe)
163				prog.Recipes = append(prog.Recipes, decl)
164				errs = append(errs, recipeErrs...)
165			case entry.Signal != nil:
166				prog.Signals = append(prog.Signals, rawToSignal(entry.Signal))
167			case entry.Projection != nil:
168				switch entry.Projection.Kind {
169				case "partition":
170					prog.ProjectionPartitions = append(prog.ProjectionPartitions, rawToProjectionPartition(entry.Projection))
171				case "score":
172					prog.ProjectionScores = append(prog.ProjectionScores, rawToProjectionScore(entry.Projection))
173				case "mapping":
174					prog.ProjectionMappings = append(prog.ProjectionMappings, rawToProjectionMapping(entry.Projection))
175				}
176			case entry.Route != nil:
177				hasDirectRoutes = true
178				prog.Routes = append(prog.Routes, rawToRoute(entry.Route))
179			case entry.DecisionTree != nil:
180				treeCount++
181				routes, treeErrs := rawDecisionTreeToRoutes(entry.DecisionTree, treeCount-1)
182				prog.Routes = append(prog.Routes, routes...)
183				errs = append(errs, treeErrs...)
184			case entry.Model != nil:
185				prog.Models = append(prog.Models, rawToModelDecl(entry.Model))
186			case entry.Plugin != nil:
187				prog.Plugins = append(prog.Plugins, rawToPlugin(entry.Plugin))
188			case entry.TestBlock != nil:
189				prog.TestBlocks = append(prog.TestBlocks, rawToTestBlock(entry.TestBlock))
190			}
191		}
192		if hasDirectRoutes && treeCount > 0 {
193			errs = append(errs, fmt.Errorf("DECISION_TREE and ROUTE declarations cannot coexist in the same program. Use only DECISION_TREE (for if/else conditional logic) or only ROUTE (for priority-based routing with WHEN clauses), not both"))
194		}
195		return prog, errs
196	}
