200			dst.Strategy = src.Strategy
201		}
202		dst.Entrypoints = append(dst.Entrypoints, src.Entrypoints...)
203		dst.Recipes = append(dst.Recipes, src.Recipes...)
204		dst.Signals = append(dst.Signals, src.Signals...)
205		dst.ProjectionPartitions = append(dst.ProjectionPartitions, src.ProjectionPartitions...)
206		dst.ProjectionScores = append(dst.ProjectionScores, src.ProjectionScores...)
207		dst.ProjectionMappings = append(dst.ProjectionMappings, src.ProjectionMappings...)
208		dst.Routes = append(dst.Routes, src.Routes...)
209		dst.Models = append(dst.Models, src.Models...)
210		dst.Plugins = append(dst.Plugins, src.Plugins...)
211		dst.TestBlocks = append(dst.TestBlocks, src.TestBlocks...)
212	}
