376	func rawToRoute(r *rawRouteDecl) *RouteDecl {
377		route := &RouteDecl{
378			Name: unquoteIdent(r.Name),
379			Pos:  posFromLexer(r.Pos),
380		}
381	
382		// Process options
383		for _, opt := range r.Opts {
384			if opt.Key == "description" && opt.Value != nil && opt.Value.Str != nil {
385				route.Description = unquote(*opt.Value.Str)
386			}
387		}
388	
389		// Process body items
390		for _, item := range r.Body {
391			switch {
392			case item.Priority != nil:
393				route.Priority = *item.Priority
394			case item.Tier != nil:
395				route.Tier = *item.Tier
396			case item.When != nil:
397				route.When = toBoolExpr(item.When)
398			case item.Model != nil:
399				for _, m := range item.Model.Models {
400					route.Models = append(route.Models, rawToModelRef(m))
401				}
402			case item.Algorithm != nil:
403				route.Algorithm = rawToAlgo(item.Algorithm)
404			case item.Plugin != nil:
405				route.Plugins = append(route.Plugins, rawToPluginRef(item.Plugin))
406			case item.Description != nil:
407				route.Description = unquote(*item.Description)
408			case item.CandidateFor != nil:
409				route.CandidateIterations = append(route.CandidateIterations, rawToCandidateIteration(item.CandidateFor))
410			case item.Emit != nil:
411				route.Emits = append(route.Emits, rawToEmitDecl(item.Emit))
412			}
413		}
414	
415		return route
416	}
