517	// ---------- Boolean Expression Conversion ----------
518	
519	func toBoolExpr(top *BoolExprTop) BoolExpr {
520		if top == nil || len(top.Terms) == 0 {
521			return nil
522		}
523		result := toAndExpr(top.Terms[0])
524		for i := 1; i < len(top.Terms); i++ {
525			right := toAndExpr(top.Terms[i])
526			result = &BoolOr{Left: result, Right: right, Pos: posFromLexer(top.Pos)}
527		}
528		return result
529	}
530	
531	func toAndExpr(term *BoolAndTerm) BoolExpr {
532		if term == nil || len(term.Factors) == 0 {
533			return nil
534		}
535		result := toFactorExpr(term.Factors[0])
536		for i := 1; i < len(term.Factors); i++ {
537			right := toFactorExpr(term.Factors[i])
538			result = &BoolAnd{Left: result, Right: right, Pos: posFromLexer(term.Pos)}
539		}
540		return result
541	}
542	
543	func toFactorExpr(f *BoolFactor) BoolExpr {
544		if f == nil {
545			return nil
546		}
547		pos := posFromLexer(f.Pos)
548		switch {
549		case f.Not != nil:
550			return &BoolNot{Expr: toFactorExpr(f.Not), Pos: pos}
551		case f.Paren != nil:
552			return toBoolExpr(f.Paren)
553		case f.SignalRef != nil:
554			return &SignalRefExpr{
555				SignalType: f.SignalRef.SignalType,
556				SignalName: unquote(f.SignalRef.SignalName),
557				Fields:     entriesToMap(f.SignalRef.Fields),
558				Pos:        pos,
559			}
560		}
561		return nil
562	}
