564	// ---------- Field / Value Conversion ----------
565	
566	func entriesToMap(entries []*FieldEntry) map[string]Value {
567		result := make(map[string]Value, len(entries))
568		for _, e := range entries {
569			if e != nil && e.Value != nil {
570				result[e.Key] = valToValue(e.Value)
571			}
572		}
573		return result
574	}
575	
576	func valToValue(v *Val) Value {
577		if v == nil {
578			return nil
579		}
580		switch {
581		case v.Str != nil:
582			return StringValue{V: unquote(*v.Str)}
583		case v.Float != nil:
584			return FloatValue{V: *v.Float}
585		case v.Int != nil:
586			return IntValue{V: *v.Int}
587		case v.Bool != nil:
588			return BoolValue{V: *v.Bool == "true"}
589		case v.ArrayVal != nil:
590			items := make([]Value, 0, len(v.ArrayVal.Items))
591			for _, item := range v.ArrayVal.Items {
592				items = append(items, valToValue(item))
593			}
594			return ArrayValue{Items: items}
595		case v.Object != nil:
596			return ObjectValue{Fields: entriesToMap(v.Object)}
597		case v.BareStr != nil:
598			return StringValue{V: *v.BareStr}
599		}
600		return nil
601	}
