605	// unquote removes surrounding quotes and handles escapes.
606	func unquote(s string) string {
607		if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
608			if unq, err := strconv.Unquote(s); err == nil {
609				return unq
610			}
611			return s[1 : len(s)-1]
612		}
613		return s
614	}
