641		TOKEN_ALGORITHM
642		TOKEN_FOR
643		TOKEN_IN
644		TOKEN_AND
645		TOKEN_OR
646		TOKEN_NOT
647		TOKEN_LBRACE
648		TOKEN_RBRACE
649		TOKEN_LPAREN
650		TOKEN_RPAREN
651		TOKEN_LBRACKET
652		TOKEN_RBRACKET
653		TOKEN_COLON
654		TOKEN_COMMA
