687	// Lex tokenizes the DSL source (backward compatibility for validator).
688	func Lex(input string) ([]Token, []error) {
689		lex, err := dslLexer.Lex("", strings.NewReader(input))
690		if err != nil {
691			return nil, []error{err}
692		}
693	
694		keywordMap := map[string]TokenType{
695			"SIGNAL": TOKEN_SIGNAL, "ROUTE": TOKEN_ROUTE,
696			"PLUGIN": TOKEN_PLUGIN, "TEST": TOKEN_IDENT,
697			"PRIORITY": TOKEN_PRIORITY, "TIER": TOKEN_IDENT, "WHEN": TOKEN_WHEN,
698			"MODEL": TOKEN_MODEL, "ALGORITHM": TOKEN_ALGORITHM,
699			"FOR": TOKEN_FOR, "IN": TOKEN_IN,
700			"AND": TOKEN_AND, "OR": TOKEN_OR, "NOT": TOKEN_NOT,
701			"true": TOKEN_BOOL, "false": TOKEN_BOOL,
702		}
703		punctMap := map[lexer.TokenType]TokenType{}
704	
705		symMap := dslLexer.Symbols()
706		identSym := symMap["Ident"]
707		stringSym := symMap["String"]
708		intSym := symMap["Int"]
709		floatSym := symMap["Float"]
710		eofSym := symMap["EOF"]
711		lbraceSym := symMap["LBrace"]
712		rbraceSym := symMap["RBrace"]
713		lparenSym := symMap["LParen"]
714		rparenSym := symMap["RParen"]
715		lbracketSym := symMap["LBracket"]
716		rbracketSym := symMap["RBracket"]
717		colonSym := symMap["Colon"]
718		commaSym := symMap["Comma"]
719		equalsSym := symMap["Equals"]
720		arrowSym := symMap["Arrow"]
721		greaterThanSym := symMap["GreaterThan"]
722		commentSym := symMap["Comment"]
723		wsSym := symMap["Whitespace"]
724	
725		punctMap[lbraceSym] = TOKEN_LBRACE
726		punctMap[rbraceSym] = TOKEN_RBRACE
727		punctMap[lparenSym] = TOKEN_LPAREN
728		punctMap[rparenSym] = TOKEN_RPAREN
729		punctMap[lbracketSym] = TOKEN_LBRACKET
730		punctMap[rbracketSym] = TOKEN_RBRACKET
731		punctMap[colonSym] = TOKEN_COLON
732		punctMap[commaSym] = TOKEN_COMMA
733		punctMap[equalsSym] = TOKEN_EQUALS
734		_ = arrowSym
735		_ = greaterThanSym
736	
737		var tokens []Token
738		for {
739			t, err := lex.Next()
740			if err != nil {
741				return nil, []error{err}
742			}
743	
744			pos := Position{Line: t.Pos.Line, Column: t.Pos.Column}
745	
746			switch t.Type {
747			case eofSym:
748				tokens = append(tokens, Token{Type: TOKEN_EOF, Literal: "", Pos: pos})
749				return tokens, nil
750			case wsSym, commentSym:
751				continue
752			case identSym:
753				if kwType, ok := keywordMap[t.Value]; ok {
754					tokens = append(tokens, Token{Type: kwType, Literal: t.Value, Pos: pos})
755				} else {
756					tokens = append(tokens, Token{Type: TOKEN_IDENT, Literal: t.Value, Pos: pos})
757				}
758			case stringSym:
759				tokens = append(tokens, Token{Type: TOKEN_STRING, Literal: unquote(t.Value), Pos: pos})
760			case intSym:
761				tokens = append(tokens, Token{Type: TOKEN_INT, Literal: t.Value, Pos: pos})
762			case floatSym:
763				tokens = append(tokens, Token{Type: TOKEN_FLOAT, Literal: t.Value, Pos: pos})
764			default:
765				if pType, ok := punctMap[t.Type]; ok {
766					tokens = append(tokens, Token{Type: pType, Literal: t.Value, Pos: pos})
767				}
768			}
769		}
770	}
771	
772	// LookupIdent returns the token type for an identifier string.
773	func LookupIdent(ident string) TokenType {
774		keywords := map[string]TokenType{
775			"SIGNAL": TOKEN_SIGNAL, "ROUTE": TOKEN_ROUTE,
776			"PLUGIN": TOKEN_PLUGIN, "TEST": TOKEN_IDENT,
777			"PRIORITY": TOKEN_PRIORITY, "TIER": TOKEN_IDENT, "WHEN": TOKEN_WHEN,
778			"MODEL": TOKEN_MODEL, "ALGORITHM": TOKEN_ALGORITHM,
779			"FOR": TOKEN_FOR, "IN": TOKEN_IN,
780			"AND": TOKEN_AND, "OR": TOKEN_OR, "NOT": TOKEN_NOT,
781			"true": TOKEN_BOOL, "false": TOKEN_BOOL,
782		}
783		if tok, ok := keywords[ident]; ok {
784			return tok
785		}
786		return TOKEN_IDENT
787	}
788	
789	// isIdentPart returns true if ch is valid in a DSL identifier.
790	func isIdentPart(ch rune) bool {
791		return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
792			(ch >= '0' && ch <= '9') || ch == '_' || ch == '-' || ch == '.' || ch == '/'
793	}
