23	// NewFileStoreClient creates a new OpenAI File Store client
24	func NewFileStoreClient(baseURL string, apiKey string) *FileStoreClient {
25		return &FileStoreClient{
26			httpClient: &http.Client{
27				Timeout: 300 * time.Second, // File uploads can take time
28				Transport: &http.Transport{
29					MaxIdleConns:        100,
30					MaxIdleConnsPerHost: 10,
31					IdleConnTimeout:     90 * time.Second,
32				},
33			},
34			baseURL: baseURL,
35			apiKey:  apiKey,
36		}
37	}
