39	// File represents an OpenAI file
40	type File struct {
41		ID            string `json:"id"`
42		Object        string `json:"object"`
43		Bytes         int64  `json:"bytes"`
44		CreatedAt     int64  `json:"created_at"`
45		Filename      string `json:"filename"`
46		Purpose       string `json:"purpose"`
47		Status        string `json:"status,omitempty"`
48		StatusDetails string `json:"status_details,omitempty"`
49	}
