51	// FileListResponse represents the response from listing files
52	type FileListResponse struct {
53		Object  string `json:"object"`
54		Data    []File `json:"data"`
55		FirstID string `json:"first_id,omitempty"`
56		LastID  string `json:"last_id,omitempty"`
57		HasMore bool   `json:"has_more"`
58	}
59	
60	// UploadFile uploads a file to OpenAI's file store
61	// purpose should be "assistants" for vector store usage
62	func (c *FileStoreClient) UploadFile(ctx context.Context, fileReader io.Reader, filename string, purpose string) (*File, error) {
63		// Create multipart form
64		var buf bytes.Buffer
65		writer := multipart.NewWriter(&buf)
66	
67		// Add purpose field
68		if err := writer.WriteField("purpose", purpose); err != nil {
69			return nil, fmt.Errorf("failed to write purpose field: %w", err)
70		}
71	
72		// Add file field
73		fileWriter, createErr := writer.CreateFormFile("file", filename)
74		if createErr != nil {
75			return nil, fmt.Errorf("failed to create form file: %w", createErr)
76		}
77	
78		if _, copyErr := io.Copy(fileWriter, fileReader); copyErr != nil {
79			return nil, fmt.Errorf("failed to copy file content: %w", copyErr)
80		}
81	
82		if err := writer.Close(); err != nil {
83			return nil, fmt.Errorf("failed to close multipart writer: %w", err)
84		}
85	
86		// Create request
87		req, err := http.NewRequestWithContext(ctx, "POST", c.baseURL+"/v1/files", &buf)
88		if err != nil {
89			return nil, fmt.Errorf("failed to create request: %w", err)
90		}
91	
92		req.Header.Set("Content-Type", writer.FormDataContentType())
93		req.Header.Set("Authorization", "Bearer "+c.apiKey)
94	
95		// Execute request
96		resp, err := c.httpClient.Do(req)
97		if err != nil {
98			return nil, fmt.Errorf("failed to upload file: %w", err)
99		}
100		defer resp.Body.Close()
101	
102		if resp.StatusCode != http.StatusOK {
103			body, _ := io.ReadAll(io.LimitReader(resp.Body, 1024))
104			return nil, fmt.Errorf("file upload failed with status %d: %s", resp.StatusCode, string(body))
105		}
106	
107		var file File
108		if err := json.NewDecoder(resp.Body).Decode(&file); err != nil {
109			return nil, fmt.Errorf("failed to decode response: %w", err)
110		}
111	
112		logging.Infof("Uploaded file %s (ID: %s, size: %d bytes)", filename, file.ID, file.Bytes)
113		return &file, nil
114	}
