129			req.URL.RawQuery = q.Encode()
130		}
131	
132		resp, err := c.httpClient.Do(req)
133		if err != nil {
134			return nil, fmt.Errorf("failed to list files: %w", err)
135		}
136		defer resp.Body.Close()
137	
138		if resp.StatusCode != http.StatusOK {
