202	
203	// DownloadFile downloads file content
204	func (c *FileStoreClient) DownloadFile(ctx context.Context, fileID string) ([]byte, error) {
205		req, err := http.NewRequestWithContext(ctx, "GET", fmt.Sprintf("%s/v1/files/%s/content", c.baseURL, fileID), nil)
206		if err != nil {
207			return nil, fmt.Errorf("failed to create request: %w", err)
208		}
209	
210		req.Header.Set("Authorization", "Bearer "+c.apiKey)
211	
212		resp, err := c.httpClient.Do(req)
213		if err != nil {
214			return nil, fmt.Errorf("failed to download file: %w", err)
215		}
216		defer resp.Body.Close()
217	
218		if resp.StatusCode != http.StatusOK {
219			body, _ := io.ReadAll(io.LimitReader(resp.Body, 1024))
220			return nil, fmt.Errorf("download file failed with status %d: %s", resp.StatusCode, string(body))
221		}
222	
223		content, err := io.ReadAll(resp.Body)
224		if err != nil {
225			return nil, fmt.Errorf("failed to read file content: %w", err)
226		}
227	
228		return content, nil
229	}
