461	// matchesDomainCondition checks if any of the detected domains match the given category name
462	// A match occurs if:
463	// 1. The detected domain equals the category name directly, OR
464	// 2. The detected domain is in the category's mmlu_categories list
465	func (e *DecisionEngine) matchesDomainCondition(categoryName string, detectedDomains []string) bool {
466		// Direct match: detected domain equals the category name
467		if slices.Contains(detectedDomains, categoryName) {
468			return true
469		}
470	
471		// Check if any detected domain is in the category's mmlu_categories
472		for _, cat := range e.categories {
473			if cat.Name == categoryName {
474				for _, detectedDomain := range detectedDomains {
475					if slices.Contains(cat.MMLUCategories, detectedDomain) {
476						return true
477					}
478				}
479				break // Found the category, no need to continue
480			}
481		}
482		return false
483	}
